USE aplikasi_game_clicker;

ALTER TABLE players 
    ADD COLUMN IF NOT EXISTS coins BIGINT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS auto_click_level INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS chain_damage_level INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS coin_income_level INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS thunder_level INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS thunder_counter INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS gacha_damage INT DEFAULT 0,
    ADD COLUMN IF NOT EXISTS gacha_clicks INT DEFAULT 0;

ALTER TABLE monsters ADD COLUMN IF NOT EXISTS effect_description TEXT;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE monsters;

